use futureox_design_kernel::{interop, design_system, editing::{DocumentEditor, DocumentPatch}};
use serde_json::{Value, json};
use std::io::Write;
const PAINT: &str = "11111111-1111-4111-8111-111111111111";
const TEXT: &str = "22222222-2222-4222-8222-222222222222";
// Independent canonical fixture, not generated by the exporter under test.
fn archive() -> Vec<u8> {
    let fill = json!({"_class":"fill","isEnabled":true,"fillType":0,"color":{"_class":"color","red":1,"green":0,"blue":0,"alpha":0.5}});
    let text = json!({"_class":"textStyle","encodedAttributes":{
        "MSAttributedStringFontAttribute":{"_class":"fontDescriptor","attributes":{"name":"default","size":16}},
        "kerning":2,"textStyleBasicParagraphStyle":{"_class":"paragraphStyle","alignment":2,"minimumLineHeight":24,"maximumLineHeight":24,"paragraphSpacing":3,"firstLineHeadIndent":0}}});
    let document = json!({"_class":"document","pages":[{"_ref":"pages/p"}],
        "layerStyles":{"_class":"sharedStyleContainer","objects":[{"_class":"sharedStyle","do_objectID":PAINT,"name":"Brand","value":{"_class":"style","fills":[fill.clone()]}}]},
        "layerTextStyles":{"_class":"sharedTextStyleContainer","objects":[{"_class":"sharedStyle","do_objectID":TEXT,"name":"Body","value":{"_class":"style","textStyle":text.clone()}}]}});
    let page = json!({"_class":"page","do_objectID":"p","name":"Page","layers":[
        {"_class":"rectangle","do_objectID":"r","name":"Rectangle","sharedStyleID":PAINT,"frame":{"x":0,"y":0,"width":100,"height":100},"style":{"fills":[fill]}},
        {"_class":"text","do_objectID":"t","name":"Text","sharedStyleID":TEXT,"frame":{"x":0,"y":100,"width":100,"height":30},"style":{"textStyle":text},"attributedString":{"_class":"attributedString","string":"Editable","attributes":[]}}
    ]});
    let mut zip = zip::ZipWriter::new(std::io::Cursor::new(Vec::new()));
    for (name, value) in [("meta.json",json!({"appVersion":"fixture"})),("document.json",document),("pages/p.json",page)] {
        zip.start_file(name, zip::write::SimpleFileOptions::default()).unwrap(); zip.write_all(&serde_json::to_vec(&value).unwrap()).unwrap();
    }
    zip.finish().unwrap().into_inner()
}
#[test]
fn canonical_shared_styles_are_live_after_import_export_edit_and_undo() {
    let mut doc = interop::import_sketch_report(&archive()).unwrap().document;
    assert_eq!(doc.design_system.as_ref().unwrap().styles.len(), 2);
    assert_eq!(doc.nodes["r"].style_refs["fills"], PAINT); assert_eq!(doc.nodes["t"].style_refs["textStyle"], TEXT);
    design_system::resolve(&mut doc).unwrap(); assert_eq!(doc.nodes["r"].fills[0].opacity, 0.5);
    let style = doc.nodes["t"].text_style.as_ref().unwrap();
    assert_eq!(style.align, "center"); assert_eq!(style.line_height, 1.5); assert_eq!(style.letter_spacing, 2.); assert_eq!(style.paragraph_spacing, 3.);
    let bytes = interop::export_sketch(&doc).unwrap(); let files = interop::read_zip_public(&bytes).unwrap();
    if let Ok(path) = std::env::var("SKETCH_RESOURCE_EVIDENCE") {
        std::fs::create_dir_all(&path).unwrap();
        std::fs::write(format!("{path}/canonical-input.sketch"), archive()).unwrap();
        std::fs::write(format!("{path}/canonical-export.sketch"), &bytes).unwrap();
    }
    let json: Value = serde_json::from_slice(&files["document.json"]).unwrap();
    assert_eq!(json["layerTextStyles"]["_class"], "sharedTextStyleContainer");
    for container in ["layerStyles", "layerTextStyles"] {
        let style = &json[container]["objects"][0]; assert_eq!(style["_class"], "sharedStyle"); assert!(style.get("style").is_none()); assert_eq!(style["value"]["_class"], "style");
    }
    let back = interop::import_sketch_report(&bytes).unwrap().document;
    let mut editor = DocumentEditor::new(back).unwrap(); let before = editor.document().clone(); let mut edited = before.clone();
    edited.design_system.as_mut().unwrap().styles.get_mut(PAINT).unwrap().value[0]["color"] = json!("#00ff00");
    edited.design_system.as_mut().unwrap().styles.get_mut(TEXT).unwrap().value["align"] = json!("end");
    editor.apply(editor.revision(), DocumentPatch::between(&before, &edited).unwrap()).unwrap();
    let mut resolved = editor.document().clone(); design_system::resolve(&mut resolved).unwrap();
    assert_eq!(resolved.nodes["r"].fills[0].color, "#00ff00"); assert_eq!(resolved.nodes["t"].text_style.as_ref().unwrap().align, "end");
    editor.undo().unwrap(); assert_eq!(editor.document(), &before); editor.redo().unwrap();
    let mut resolved = interop::import_sketch_report(&interop::export_sketch(editor.document()).unwrap()).unwrap().document;
    design_system::resolve(&mut resolved).unwrap(); assert_eq!(resolved.nodes["r"].fills[0].color, "#00ff00"); assert_eq!(resolved.nodes["t"].text_style.as_ref().unwrap().align, "end");
}
#[test]
fn kernel_style_ids_roundtrip_through_uuid_wire_ids() {
    let mut doc = interop::import_sketch_report(&archive()).unwrap().document;
    let system = doc.design_system.as_mut().unwrap(); let style = system.styles.remove(PAINT).unwrap(); system.styles.insert("ops-accent".into(), style);
    doc.nodes.get_mut("r").unwrap().style_refs.insert("fills".into(), "ops-accent".into());
    let bytes = interop::export_sketch(&doc).unwrap(); let files = interop::read_zip_public(&bytes).unwrap();
    let json: Value = serde_json::from_slice(&files["document.json"]).unwrap(); assert_eq!(json["layerStyles"]["objects"][0]["do_objectID"].as_str().unwrap().len(),36);
    let back = interop::import_sketch_report(&bytes).unwrap().document;
    assert!(back.design_system.as_ref().unwrap().styles.contains_key("ops-accent")); assert_eq!(back.nodes["r"].style_refs["fills"], "ops-accent");
}

fn with_changed_document(change: impl FnOnce(&mut Value)) -> Vec<u8> {
    let mut files = interop::read_zip_public(&archive()).unwrap();
    let mut document: Value = serde_json::from_slice(&files["document.json"]).unwrap();
    change(&mut document);
    files.insert("document.json".into(), serde_json::to_vec(&document).unwrap());
    let mut zip = zip::ZipWriter::new(std::io::Cursor::new(Vec::new()));
    for (name, bytes) in files {
        zip.start_file(name, zip::write::SimpleFileOptions::default()).unwrap();
        zip.write_all(&bytes).unwrap();
    }
    zip.finish().unwrap().into_inner()
}
#[test]
fn duplicate_shared_style_wire_and_resolved_ids_are_rejected_before_adoption() {
    for mode in ["same-container", "identical-definition", "cross-container", "two-aliases", "alias-vs-wire"] {
        let bytes = with_changed_document(|document| match mode {
            "same-container" | "identical-definition" => {
                let mut duplicate = document["layerStyles"]["objects"][0].clone();
                if mode == "same-container" { duplicate["name"] = json!("Conflicting name"); }
                document["layerStyles"]["objects"].as_array_mut().unwrap().push(duplicate);
            }
            "cross-container" => document["layerTextStyles"]["objects"][0]["do_objectID"] = json!(PAINT),
            "two-aliases" => document["userInfo"] = json!({"com.futureox.design-kernel":{"sharedStyleIds":{PAINT:"same",TEXT:"same"}}}),
            "alias-vs-wire" => document["userInfo"] = json!({"com.futureox.design-kernel":{"sharedStyleIds":{PAINT:TEXT}}}),
            _ => unreachable!(),
        });
        for error in [interop::import_sketch(&bytes).unwrap_err(), interop::import_sketch_report(&bytes).err().expect("duplicate must fail")] {
            let message = error.to_string();
            assert!(message.contains("duplicate") && message.contains("shared style"), "{mode}: {message}");
        }
    }
    // A valid mapping must continue preserving separate live styles.
    let valid = with_changed_document(|document| document["userInfo"] = json!({"com.futureox.design-kernel":{"sharedStyleIds":{PAINT:"paint",TEXT:"text"}}}));
    let report = interop::import_sketch_report(&valid).unwrap();
    assert_eq!(report.document.nodes["r"].style_refs["fills"], "paint");
    assert_eq!(report.document.nodes["t"].style_refs["textStyle"], "text");
}
